"home.about.bhoomishaktiIsACollectionOf": "BhoomiShakti என்பது ஒன்றுக்கொன்று துணையாக இருக்கும் விவசாயப் புதுமைகளின் தொகுப்பு. ஒவ்வொரு திட்டமும் விவசாயத்தின் ஒரு தனிப் பகுதியைக் கவனிக்கிறது — நுண்ணறிவு, டிஜிட்டல் இணைப்பு முதல் இயந்திரங்கள், விதைகள், மண் மற்றும் புதுப்பிக்கத்தக்க கிராம வளங்கள் வரை.",
"home.about.insteadOfEightUnrelatedProjects": "தொடர்பில்லாத எட்டு திட்டங்களாக இல்லாமல், BhoomiShakti ஒரே கதையாக வேலை செய்கிறது: விவசாயத்துடன் சேர்ந்து வளரும் தொழில்நுட்பம்.",
