"home.projects.aControlledBionutrientApproachAged": "கட்டுப்படுத்தப்பட்ட உயிர் ஊட்டச்சத்து முறை — மக்கிய எரு, மட்கு உரம், மண், தேங்காய் நார்க்கழிவு (cocopeat) மற்றும் நீர்த்த சிறுநீர் — மண்ணின் உயிரியல் செயல்பாட்டுக்காக BhoomiShakti X1 மூலம் மண்ணில் கலக்கப்படுகிறது.",
