"home.projects.aProposedCircularEcosystemThat": "முன்மொழியப்பட்ட சுழற்சி சூழல் அமைப்பு — கால்நடை உயிர்க்கழிவு சேகரிப்பு, புதுப்பிக்கத்தக்க எரிசக்திக்கான காற்றில்லா செரிமானம், விவசாயத்திற்கான செரிமானக் கழிவு உரம் — அனைத்தும் டிஜிட்டல் முறையில் கண்காணிக்கப்படும்.",
