"agriDigital.live.getHelpFromTheAgriculturefocused": "விவசாயத்துக்கான AI உதவியாளரிடம் <t0>உதவி பெறுங்கள்</t0>.",
"agriDigital.live.shareFeedbackToKeepThe": "சூழல் அமைப்பு தொடர்ந்து மேம்பட உங்கள் <t0>கருத்தைப்</t0> பகிருங்கள்.",
"agriDigital.live.aBusinessProfileShowsWhat": "வணிகம் என்ன வழங்குகிறது என்பதை <t0>வணிக விவரம்</t0> காட்டுகிறது.",
"agriDigital.live.productsAndServicesAreListed": "<t0>பொருட்களும் சேவைகளும்</t0> தெளிவாகப் பட்டியலிடப்பட்டுள்ளன.",
