"agriDigital.live.theBusinessRespondsAConnection": "<t0>வணிகம் பதில் அளிக்கிறது</t0> — இணைப்பு ஏற்படுகிறது.",
"agriDigital.live.agriculturalBusinessesGetADigital": "விவசாய வணிகங்கள் டிஜிட்டல் விவரம் பெற்று விவசாயிகளை அடைகின்றன.",
"agriDigital.live.agriculturalProductsFarmersCanDiscover": "விவசாயிகள் கண்டறிந்து ஒப்பிடக்கூடிய விவசாயப் பொருட்கள்.",
"agriDigital.live.agriculturalServicesOfferedByBusinesses": "அந்தப் பகுதி வணிகங்கள் வழங்கும் விவசாய சேவைகள்.",
