"s4.overview.solarEnergyBatteryPowerControlled": "சூரிய சக்தி, பேட்டரி சக்தி, கட்டுப்படுத்தப்பட்ட அதிர்வு, விதை ஓட்ட மேலாண்மை, முதுகில் சுமக்கும் வசதி மற்றும் நிழல் — அனைத்தும் ஒரே குறைந்த விலைக் கருவியில்.",
"s4.overview.manualSeedSowingIsHard": "கையால் விதைப்பது கடினமான வேலை",
"s4.overview.unevenSeedDistribution": "சீரற்ற விதைப் பரவல்",
"s4.overview.highManualLabourRequirement": "அதிக உடல் உழைப்பு தேவை",
"s4.overview.heatStressDuringFieldWork": "வயல் வேலையின்போது வெயில் பாதிப்பு",
"s4.overview.timeconsumingSowing": "அதிக நேரம் எடுக்கும் விதைப்பு",
"s4.overview.lackOfAffordableAgriculturalMachinery": "குறைந்த விலை விவசாய இயந்திரங்கள் இல்லாமை",
"s4.overview.aPortableSolarassistedSeedSower": "எடுத்துச் செல்லக்கூடிய, சோலார் உதவியுடன் விதை விதைப்பான்",
"s4.overview.aLowcostPortableSolarassistedBackpackbased": "குறைந்த செலவில், எடுத்துச் செல்லக்கூடிய, சோலார் உதவியுடன், முதுகில் சுமக்கும் அமைப்பு — கட்டுப்படுத்தப்பட்ட, ஒப்பீட்டளவில் சீரான விதைப் பரவலைத் தருகிறது, விவசாயிக்கு வசதியையும் கூட்டுகிறது.",
"s4.overview.solar": "<t0/>சோலார்",
