"s4.how.vibrationKeepsSeedsFlowingThe": "அதிர்வு விதைகளைத் தொடர்ந்து ஓடச் செய்கிறது; வேகக் கட்டுப்பாடு பயிருக்கு ஏற்ப விதைப்பு அளவைச் சரிசெய்கிறது.",
