"s4.how.theSolarPanelInThe": "குடையில் உள்ள <t0>சோலார் பேனல்</t0> பேட்டரியை சார்ஜ் செய்கிறது.",
"s4.story.scrolldrivenSeedFlow": "ஸ்க்ரோல் செய்தால் நகரும் விதை ஓட்டம்",
"s4.story.watchS4ComeAlive": "S4 <t0>இயங்குவதைப்</t0> பாருங்கள்.",
"s4.story.scrollDownEachPartActivates": "கீழே ஸ்க்ரோல் செய்யுங்கள்: ஒவ்வொரு பகுதியும் வரிசையாக இயங்கும், விதைகள் சேமிப்பிலிருந்து இரட்டைக் குழாய்கள் வழியாக மண்ணுக்குச் செல்லும். கருத்து விளக்கப்படம்.",
"s4.story.conceptualDiagramOfBhoomishaktiS4": "BhoomiShakti S4-இன் கருத்து வரைபடம்: சோலார் குடை, பேட்டரி, வேகக் கட்டுப்பாட்டி, அதிர்வு மோட்டார், விதைச் சேமிப்பு, இரட்டைக் குழாய்கள் மற்றும் மண்",
