"s4.story.solarPanelUmbrella": "சோலார் பேனல் & குடை",
"s4.story.theSolarUmbrellaCollectsSunlight": "சோலார் குடை சூரிய ஒளியைச் சேகரிக்கிறது — அதே நேரத்தில் விவசாயிக்கு நிழலும் தருகிறது.",
"s4.story.batteryActivates": "பேட்டரி இயங்குகிறது",
"s4.story.theRechargeableBatteryStoresEnergy": "ரீசார்ஜ் செய்யக்கூடிய பேட்டரி சக்தியைச் சேமிக்கிறது — மின்சாரம் குறைவாகக் கிடைக்கும் இடங்களில் பயனுள்ளது.",
