"s4.story.seedsLeaveStorage": "விதைகள் சேமிப்பிலிருந்து வெளியேறுகின்றன",
"s4.story.seedsMoveFromTheStorage": "விதைகள் சேமிப்பு அறையிலிருந்து ஓட்டப் பாதைக்குச் செல்கின்றன.",
