"s4.farmer.solarUmbrellaARenewableenergyComponent": "<t0>☂️ சோலார் குடை</t0> — புதுப்பிக்கத்தக்க எரிசக்திப் பாகமும், விவசாயிக்கு வசதி தரும் அம்சமும்.",
