"s4.farmer.theBackpackStructureAndSolar": "முதுகுப்பை அமைப்பும் சோலார் குடையும் எடுத்துச் செல்லும் வசதி, விவசாயப் பயன் மற்றும் வயலில் வசதியை ஒன்றாகத் தருகின்றன.",
