"s4.feasibility.simplePortableLowcost": "எளியது, எடுத்துச் செல்லக்கூடியது, <t0>குறைந்த செலவு.</t0>",
"s4.feasibility.bhoomishaktiS4IsDesignedAs": "BhoomiShakti S4 கிராம விவசாயச் சூழலுக்கு ஏற்ற, குறைந்த செலவில், எடுத்துச் செல்லக்கூடிய முன்மாதிரியாக வடிவமைக்கப்பட்டுள்ளது — குறிப்பாக மின்சாரம் குறைவாகக் கிடைக்கக்கூடிய இடங்களுக்கு.",
