"s4.contact.sowSmarterUnderTheSun": "சூரியனின் கீழ், புத்திசாலித்தனமாக விதையுங்கள்.",
"s4.contact.solarEnergySmartSeedflowControl": "சூரிய சக்தி, ஸ்மார்ட் விதை ஓட்டக் கட்டுப்பாடு, எடுத்துச் செல்லக்கூடிய வடிவமைப்பு — விவசாயிக்கு ஏற்ற விதைப்பு.",
"s4.contact.sendAnEnquiry": "விசாரணை அனுப்புங்கள் <t0/>",
"s4.top.label.bhoomishaktiS4SmartSolarSeed": "BhoomiShakti S4 ஸ்மார்ட் சோலார் விதை விதைப்பான் கருத்து",
"s4.farmer.label.farmerfriendlyS4SeedSowerConcept": "விவசாயிக்கு ஏற்ற S4 விதை விதைப்பான் கருத்து",
"meta.s4.bhoomishaktiS4SmartSolarSeed": "BhoomiShakti S4 — ஸ்மார்ட் சோலார் விதை விதைப்பான்",
"s4.live.theRechargeableBatteryPowersThe": "<t0>ரீசார்ஜ் செய்யக்கூடிய பேட்டரி</t0> அமைப்புக்குச் சக்தி தருகிறது.",
"s4.live.theMotorRunsAtThe": "இயக்குநர் அமைக்கும் வேகத்தில் <t0>மோட்டார்</t0> இயங்குகிறது.",
"s4.live.vibrationKeepsSeedFlowContinuous": "<t0>அதிர்வு</t0> விதை ஓட்டத்தைத் தொடர்ந்து வைக்கிறது.",
"s4.live.seedsFlowFromTheStorage": "சேமிப்பு அறையிலிருந்து <t0>விதைகள் ஓடுகின்றன</t0>.",
"s4.live.seedsExitThroughDualDispensing": "விதைகள் <t0>இரட்டை விதைக் குழாய்கள்</t0> வழியாக வெளியேறுகின்றன.",
"s4.live.seedsReachTheSoilWith": "விதைகள் மேலும் சீரான இடைவெளியுடன் <t0>மண்ணை</t0> அடைகின்றன.",
"jeevadhara.top.soilHealthSustainableAgriculture": "மண் வளம் · நிலையான விவசாயம்",
"jeevadhara.top.jeevadharaKrishiSystem": "JeevaDhara <t0>Krishi</t0> அமைப்பு",
"jeevadhara.top.anIntegratedControlledBionutrientAnd": "நிலையான விவசாயத்துக்கான ஒருங்கிணைந்த கட்டுப்படுத்தப்பட்ட உயிர் ஊட்டச்சத்து மற்றும் இயந்திர மண் கலப்பு முறை",
"jeevadhara.top.controlledBionutritionMechanizedSoilIncorporation": "“கட்டுப்படுத்தப்பட்ட உயிர் ஊட்டம் + இயந்திரம் மூலம் மண்ணில் கலத்தல் = நிலையான மண் வளம்”",
