"jeevadhara.overview.feedTheSoilNotJust": "மண்ணுக்கு ஊட்டம் கொடுங்கள், <t0>பயிருக்கு மட்டுமல்ல.</t0>",
"jeevadhara.overview.aSustainableModelCombiningOrganic": "இயற்கை ஊட்டச்சத்து மேலாண்மை, கட்டுப்படுத்தப்பட்ட உயிர் நைட்ரஜன் இடுபொருட்கள், மண்ணின் உயிரியல் செயல்பாடு மற்றும் இயந்திரம் மூலம் மண்ணில் கலத்தல் — இவற்றை இணைக்கும் நிலையான மாதிரி.",
"jeevadhara.overview.overdependenceOnSyntheticFertilizers": "செயற்கை உரங்களை அதிகம் சார்ந்திருத்தல்",
"jeevadhara.overview.soilDegradationAndAcidification": "மண் சீர்கேடு மற்றும் அமிலத்தன்மை",
"jeevadhara.overview.nutrientImbalance": "ஊட்டச்சத்து சமநிலையின்மை",
"jeevadhara.overview.reducedSoilBiodiversity": "மண் உயிர்ப் பன்மை குறைதல்",
"jeevadhara.overview.declineInEarthwormPopulations": "மண்புழுக்கள் எண்ணிக்கை குறைதல்",
"jeevadhara.overview.highLabourRequirementForOrganic": "இயற்கை விவசாயத்துக்கு அதிக உழைப்பு தேவை",
"jeevadhara.overview.unevenNutrientDistribution": "சீரற்ற ஊட்டச்சத்து பரவல்",
"jeevadhara.overview.aControlledBionutrientSystemX1": "கட்டுப்படுத்தப்பட்ட உயிர் ஊட்டச்சத்து அமைப்பு + X1",
"jeevadhara.overview.agedManureCompostSoilCocopeat": "மக்கிய எரு, மட்கு உரம், மண், தேங்காய் நார்க்கழிவு (cocopeat) மற்றும் நீர்த்த சிறுநீர் கட்டுப்படுத்தப்பட்ட உயிர் ஊட்டச்சத்து கலவையாகத் தயாரிக்கப்பட்டு, நிலைப்படுத்தப்பட்டு, பிறகு BhoomiShakti X1 மூலம் மண்ணில் கலக்கப்படுகிறது.",
"jeevadhara.overview.objectives": "நோக்கங்கள்",
"jeevadhara.overview.developAControlledBionitrogenSystem": "கட்டுப்படுத்தப்பட்ட உயிர் நைட்ரஜன் அமைப்பை உருவாக்குதல்",
"jeevadhara.overview.improveSoilBiologicalActivityAnd": "மண்ணின் உயிரியல் செயல்பாட்டை மேம்படுத்தி மண்புழுக்களுக்கு உதவுதல்",
"jeevadhara.overview.enhanceSustainableCropProductivity": "நிலையான பயிர் உற்பத்தியை அதிகரித்தல்",
"jeevadhara.overview.reduceDependenceOnChemicalFertilizers": "ரசாயன உரங்களைச் சார்ந்திருப்பதைக் குறைத்தல்",
