"jeevadhara.x1.manualMixingIsTimeconsumingLabourintensive": "கையால் கலப்பது அதிக நேரமும் உழைப்பும் எடுக்கும், சீராகப் பரப்புவதும் கடினம். X1 ரோட்டரி இரும்பு அலகுகளால் கலவையை மண்ணில் கலக்கிறது.",
