"jeevadhara.live.bhoomishaktiX1MixesTheBionutrients": "<t0>BhoomiShakti X1</t0> உயிர் ஊட்டச்சத்துகளை மண்ணில் கலக்கிறது.",
"jeevadhara.live.incorporationSupportsSoilBiologicalActivity": "கலத்தல் <t0>மண்ணின் உயிரியல் செயல்பாட்டுக்கு</t0> உதவுகிறது.",
"jeevadhara.live.theAimSustainableCropProduction": "நோக்கம்: <t0>நிலையான பயிர் உற்பத்தி</t0>.",
"jeevadhara.live.step0PrepareSolutionDiluted": "<t0>படி {0} · கரைசலைத் தயாரிக்கவும்:</t0> {1}:{2} விகிதத்தில் நீர்த்த சிறுநீர்.",
"jeevadhara.live.step0AddGraduallySlowly": "<t0>படி {0} · மெதுவாகச் சேர்க்கவும்:</t0> கரைசலை உலர் கலவையில் மெதுவாகச் சேர்க்கவும்.",
"jeevadhara.live.step0KeepItMoist": "<t0>படி {0} · ஈரமாக வைக்கவும்:</t0> ஈரப்பதமான பதத்தைப் பராமரிக்கவும்.",
"jeevadhara.live.step0StabilizeAllow12": "<t0>படி {0} · நிலைப்படுத்தவும்:</t0> {1}–{2} மணி நேரம் விடவும்.",
"jeevadhara.live.theMixIsLoadedOr": "கலவை வயலில் <t0>ஏற்றப்படுகிறது அல்லது இடப்படுகிறது</t0>.",
"jeevadhan.top.circularRuralEconomyRenewableAgriculture": "சுழற்சி கிராமப் பொருளாதாரம் & புதுப்பிக்கத்தக்க விவசாயம்",
"jeevadhan.top.turningRuralBiomassIntoRenewable": "கிராம உயிர்க்கழிவை புதுப்பிக்கத்தக்க மதிப்பாக மாற்றுதல் — உள்ளூரில் கிடைக்கும் கால்நடை உயிர்க்கழிவை பயனுள்ள புதுப்பிக்கத்தக்க எரிசக்தி மற்றும் விவசாய வளங்களாக மாற்றுதல்.",
"jeevadhan.top.transformRuralBiomassFromA": "“கிராம உயிர்க்கழிவை ஒரு கழிவுப் பிரச்சினையிலிருந்து எரிசக்தி, மதிப்பு மற்றும் விவசாய நிலைத்தன்மையின் மூலமாக மாற்றுங்கள்.”",
