"jeevadhan.overview.fromAWasteChallengeTo": "கழிவுப் பிரச்சினையிலிருந்து <t0>கிராம மதிப்பு வரை.</t0>",
"jeevadhan.overview.aProposedCircularBiomasstoresourceEcosystem": "கால்நடைகள், விவசாயிகள், கிராம உயிர்க்கழிவு, புதுப்பிக்கத்தக்க எரிசக்தி, விவசாயம் மற்றும் டிஜிட்டல் தொழில்நுட்பத்தை இணைக்கும், உயிர்க்கழிவை வளமாக மாற்றும் முன்மொழியப்பட்ட சுழற்சி சூழல் அமைப்பு.",
"jeevadhan.overview.ruralBiomassIsUnderutilized": "கிராம உயிர்க்கழிவு சரியாகப் பயன்படுத்தப்படுவதில்லை",
"jeevadhan.overview.unorganizedCattledungCollection": "ஒழுங்கற்ற சாணச் சேகரிப்பு",
"jeevadhan.overview.limitedBiomassUtilization": "உயிர்க்கழிவின் குறைந்த பயன்பாடு",
"jeevadhan.overview.dependenceOnConventionalEnergySources": "வழக்கமான எரிசக்தி மூலங்களைச் சார்ந்திருத்தல்",
"jeevadhan.overview.noOrganizedDigitalBiomassNetwork": "ஒழுங்கான டிஜிட்டல் உயிர்க்கழிவு நெட்வொர்க் இல்லை",
"jeevadhan.overview.needForSustainableOrganicresourceManagement": "நிலையான இயற்கை வள மேலாண்மை தேவை",
"jeevadhan.overview.lostOpportunityToRecoverBiological": "விவசாயத்துக்கான உயிரியல் வளங்களை மீட்கும் வாய்ப்பு வீணாகிறது",
"jeevadhan.overview.aCircularBiomasstoresourceEcosystem": "உயிர்க்கழிவை வளமாக மாற்றும் சுழற்சி சூழல் அமைப்பு",
"jeevadhan.overview.organizedBiomassCollectionProcessingThrough": "ஒழுங்கான உயிர்க்கழிவு சேகரிப்பு, காற்றில்லா செரிமானம் மூலம் பதப்படுத்துதல், புதுப்பிக்கத்தக்க எரிசக்தி வழி மற்றும் செரிமானக் கழிவு உரத்தின் சரியான பயன்பாடு — விவசாயிகளின் பங்கேற்பு, டிஜிட்டல் கண்காணிப்பு மற்றும் பரிவர்த்தனைப் பதிவுகளுடன்.",
"jeevadhan.overview.howCanLocallyAvailableCattle": "உள்ளூரில் கிடைக்கும் கால்நடை உயிர்க்கழிவை எப்படி ஒழுங்குபடுத்தி, பதப்படுத்தி, பயனுள்ள புதுப்பிக்கத்தக்க எரிசக்தி மற்றும் விவசாய வளங்களாக மாற்றி, கிராம சமூகங்களுக்கு மதிப்பை உருவாக்கலாம்?",
