"jeevadhan.how.farmersOrLivestockOwnersRegister": "விவசாயிகள் அல்லது கால்நடை உரிமையாளர்கள் பதிவு செய்கின்றனர்: சுயவிவரம், கால்நடை விவரங்கள், கிடைக்கும் உயிர்க்கழிவு அளவு மற்றும் சேகரிப்பு இடம்.",
