"jeevadhan.how.farmersProvideCattleDungTo": "விவசாயிகள் கிராம அளவிலான சேகரிப்பு நெட்வொர்க்குக்கு சாணம் வழங்குகின்றனர். பதிவு: விவசாயி → அளவு → சேகரிப்பு → பணம் / பரிவர்த்தனை.",
