"jeevadhan.how.digitalMonitoring": "டிஜிட்டல் கண்காணிப்பு",
"jeevadhan.how.trackBiomassCollectedCollectionRequests": "சேகரித்த உயிர்க்கழிவு, சேகரிப்பு கோரிக்கைகள், பதப்படுத்தும் நிலை, எரிசக்தி மற்றும் செரிமானக் கழிவு பதிவுகள், விவசாயி பரிவர்த்தனைகளைக் கண்காணியுங்கள்.",
