"jeevadhan.future.purificationUpgradingCompressionAndCertified": "சுத்திகரிப்பு, மேம்படுத்தல், அழுத்தமாக்கல் மற்றும் சான்றளிக்கப்பட்ட விநியோகம் — தொழில்நுட்ப ரீதியாகவும் சட்ட ரீதியாகவும் சாத்தியமான இடங்களில்",
