"jeevadhan.live.valueReturnsToFarmersAnd": "மதிப்பு <t0>விவசாயிகளுக்கே</t0> திரும்புகிறது — சுழற்சி தொடர்கிறது.",
"jeevadhan.live.cattleDungAndOrganicBiomass": "சாணமும் இயற்கை உயிர்க்கழிவும் — கழிவாக அல்ல, வளமாகப் பார்க்கப்படுகின்றன.",
"jeevadhan.live.aVillagelevelCollectionNetworkRecorded": "டிஜிட்டல் முறையில் பதிவு செய்யப்படும் கிராம அளவிலான சேகரிப்பு நெட்வொர்க்.",
"jeevadhan.live.biomassIsTransportedToAn": "உயிர்க்கழிவு பொருத்தமான பதப்படுத்தும் / பயோகேஸ் மையத்துக்குக் கொண்டு செல்லப்படுகிறது.",
"jeevadhan.live.anaerobicDigestionBreaksTheBiomass": "காற்றில்லா செரிமானம் உயிர்க்கழிவைச் சிதைக்கிறது.",
"jeevadhan.live.anaerobicDigestionProducesBiogasPurified": "காற்றில்லா செரிமானம் பயோகேஸை உருவாக்குகிறது. சுத்திகரிக்கப்பட்ட பயோமீத்தேன் / CBG-க்கு சுத்திகரிப்பு, மேம்படுத்தல், அழுத்தமாக்கல் மற்றும் சான்றளிக்கப்பட்ட கட்டமைப்பு தேவைப்படும்.",
"jeevadhan.live.aRenewableenergyPathwayFromLocal": "உள்ளூர் வளங்களிலிருந்து புதுப்பிக்கத்தக்க எரிசக்தி வழி.",
"jeevadhan.live.potential": "சாத்தியம்",
"jeevadhan.live.processedOrganicResourcesCanReturn": "பதப்படுத்திய இயற்கை வளங்கள் பண்ணைக்கே திரும்பலாம் — சுழற்சி முழுமையாகிறது.",
