"farmerTools.weather.searchYourVillageOrUse": "உங்கள் கிராமத்தைத் தேடுங்கள் அல்லது உங்கள் தற்போதைய இருப்பிடத்தைப் பயன்படுத்துங்கள் — நீர்ப்பாசனம், வயல் வேலை மற்றும் தெளிப்புக்கான எளிய, எச்சரிக்கையான வழிகாட்டுதலுடன் {0} நாள் முன்னறிவிப்பைப் பார்க்கலாம்.",
