"farmerTools.weather.rainExpectedWhenTheForecast": "அன்றைய முன்னறிவிப்பு <t1>{0} mm அல்லது அதற்கு மேல்</t1> இருந்தால் <t0>மழை எதிர்பார்க்கப்படுகிறது</t0> — இது {1} மணி நேரத்தில் “லேசான மழை”க்கான இந்திய வானிலை ஆய்வு மையத்தின் (IMD) குறைந்தபட்ச அளவு.",
"farmerTools.weather.veryHotWhenTheForecast": "அதிகபட்ச வெப்பநிலை முன்னறிவிப்பு <t1>{0} °C அல்லது அதற்கு மேல்</t1> இருந்தால் <t0>மிகவும் வெப்பம்</t0> — இது சமவெளிப் பகுதிகளுக்கான IMD வெப்ப அலை வரம்பு (மலைப் பகுதிகளுக்குக் குறைந்த வரம்பு).",
"farmerTools.weather.possibleSprayHoursAreDaytime": "<t0>தெளிக்கக்கூடிய நேரம்</t0> என்பது மழை முன்னறிவிப்பு இல்லாத, காற்று <t1>{2} முதல் {3} km/h</t1> ({4}–{5} mph) வரை உள்ள பகல் நேரம் (காலை {0} – மாலை {1}) — பூச்சிக்கொல்லி பாதுகாப்பு வழிகாட்டுதலில் பரிந்துரைக்கப்பட்ட அளவு. காற்றே இல்லாத அமைதியான நிலையிலும் மருந்து திசைமாறிப் பரவலாம்.",
"farmerTools.weather.forecastWindIsAt0": "முன்னறிவிப்புக் காற்று {0} m உயரத்தில், உங்கள் பகுதிக்கானது — உங்கள் சரியான வயலுக்கானது அல்ல.",
"farmerTools.weather.sourcesIndiaMeteorologicalDepartmentRainfall": "ஆதாரங்கள்: <t0>இந்திய வானிலை ஆய்வு மையம்</t0> (மழை சொற்கள், <t1>வெப்ப அலை வரையறை</t1>) · <t2>Pesticide Environmental Stewardship — வானிலையை மதிப்பிடுங்கள்</t2>",
"farmerTools.weather.weatherbasedGuidanceIsInformationalAlways": "<t0>வானிலை அடிப்படையிலான வழிகாட்டுதல் தகவலுக்காக மட்டுமே.</t0> தெளிப்பதற்கு முன் எப்போதும் உள்ளூர் வயல் நிலை, பயிர் தேவை மற்றும் மருந்து லேபிள் அறிவுறுத்தல்களைக் கவனியுங்கள்.",
