"farmerTools.schemes.linksGoOnlyToOfficial": "இணைப்புகள் இந்திய அரசின் அதிகாரப்பூர்வ இணையதளங்களுக்கு மட்டுமே செல்கின்றன. அதிகாரப்பூர்வ ஆதாரம் உறுதிசெய்த உதவி எண்கள் மட்டுமே காட்டப்படுகின்றன — ஒவ்வொன்றும் அதன் ஆதாரத்தைக் காட்டுகிறது.",
