"farmerTools.schemes.centralGovernmentIncomesupportSchemeFor": "விவசாயக் குடும்பங்களுக்கான மத்திய அரசின் வருமான உதவித் திட்டம். பதிவு, eKYC மற்றும் பயனாளி நிலை அதிகாரப்பூர்வ இணையதளத்தில் கையாளப்படுகின்றன.",
"farmerTools.schemes.01IvrsHelplineSourcePib": "{0}×{1} IVRS உதவி எண் · <t0>ஆதாரம்: PIB, இந்திய அரசு ↗</t0>",
