"farmerTools.schemes.governmentsponsoredCropInsuranceSchemeThe": "அரசு ஆதரவு பெற்ற பயிர்க் காப்பீட்டுத் திட்டம். க்ருஷி ரக்ஷக் போர்ட்டல் & உதவி எண் மூலம் இழப்பீட்டுக் கோரிக்கைகள், புகார்கள் மற்றும் கேள்விகளுக்கு உதவி கிடைக்கும்.",
"farmerTools.schemes.krishiRakshakPortalHelplineSource": "க்ருஷி ரக்ஷக் போர்ட்டல் & உதவி எண் · <t0>ஆதாரம்: PIB, இந்திய அரசு ↗</t0>",
