"farmerTools.schemes.aReportOnYourSoils": "உங்கள் மண்ணின் ஊட்டச்சத்து நிலை பற்றிய அறிக்கை, உரம் மற்றும் மண் திருத்தப் பரிந்துரைகளுடன். அட்டையைப் பார்க்கவும் அச்சிடவும் இந்த இணையதளம் பயன்படுகிறது.",
