"farmerTools.schemes.answersFarmersQuestionsOnThe": "விவசாய நிபுணர்கள் மூலம் விவசாயிகளின் கேள்விகளுக்கு அவர்களின் சொந்த மொழியில் தொலைபேசியில் பதில் அளிக்கிறது. காலை {0}:{1} – மாலை {2}:{3} வரை, வாரத்தின் ஏழு நாட்களும் கிடைக்கும்.",
