"farmerTools.schemes.visitMkisangovin": "mkisan.gov.in-க்குச் செல்லுங்கள் <t0/>",
"farmerTools.schemes.eligibilityBenefitsAndApplicationSteps": "தகுதி, பலன்கள் மற்றும் விண்ணப்ப முறைகள் மாறலாம். சமீபத்திய விவரங்களுக்கு எப்போதும் அதிகாரப்பூர்வ இணையதளம் அல்லது உதவி எண்ணைச் சரிபாருங்கள். BhoomiShakti இந்த அரசு சேவைகளுடன் தொடர்புடையது அல்ல. தகவல் அக்டோபர் {0}-இல் சரிபார்க்கப்பட்டது.",
"farmerTools.main.farmerSafetyInformationNote": "விவசாயி பாதுகாப்பு & தகவல் குறிப்பு",
"farmerTools.main.theseToolsSupportYourDecisions": "இந்தக் கருவிகள் உங்கள் முடிவுகளுக்கு உதவுகின்றன; உங்கள் உள்ளூர் வேளாண் அலுவலர், க்ருஷி விஞ்ஞான் கேந்திரா அல்லது கிசான் கால் சென்டர் ({0}-{1}-{2}) ஆலோசனைக்கு மாற்று அல்ல.",
"farmerTools.main.beforeSprayingReadAndFollow": "தெளிப்பதற்கு முன், மருந்து லேபிளைப் படித்துப் பின்பற்றுங்கள், அதில் சொல்லப்பட்ட பாதுகாப்பு உபகரணங்களை அணியுங்கள்.",
"farmerTools.main.weatherForecastsCanChangeCheck": "வானிலை முன்னறிவிப்பு மாறலாம். வேலை செய்யும் நாளில் மீண்டும் சரிபாருங்கள்.",
"farmerTools.main.theLandConverterAndProfit": "நில அளவு மாற்றியும் லாபத் திட்டமிடலும் உங்கள் பிரவுசரில் மட்டுமே இயங்குகின்றன. நீங்கள் உள்ளிடுவதை BhoomiShakti பெறுவதும் இல்லை, சேமிப்பதும் இல்லை.",
"farmerTools.contact.moreThanToolsOneEcosystem": "கருவிகளை விட மேலானது — <t0>ஒரே சூழல் அமைப்பு.</t0>",
"farmerTools.contact.fromAgricultureIntelligenceToSolar": "விவசாய நுண்ணறிவு முதல் சோலார் இயந்திரங்கள், மண் வளம் வரை — விவசாயிகளுக்குத் தேவையான சேவைகளை BhoomiShakti இணைக்கிறது.",
