"team.top.oneFounderSixBuildersAnd": "ஒரு நிறுவனர், ஆறு உருவாக்குநர்கள், எட்டு புதுமைகள். பொறியியல், மென்பொருள், மண் அறிவியல் மற்றும் வடிவமைப்பு — ஒரே இணைந்த விவசாய சூழல் அமைப்பை நோக்கி.",
