"contact.main.noAMobileNumberIs": "இல்லை. மொபைல் எண் போதும். பதில் பெறும் வழியாக <t0>தொலைபேசி அழைப்பு</t0> அல்லது <t1>WhatsApp</t1> என்பதைத் தேர்ந்தெடுங்கள். மின்னஞ்சலில் பதில் கேட்டால் மட்டுமே மின்னஞ்சல் தேவை.",
"contact.main.canIRentX1Or": "இந்தப் பக்கம் மூலம் X1-ஐ வாடகைக்கு எடுக்கவோ S4-ஐ முன்பதிவு செய்யவோ முடியுமா?",
"contact.main.youCanSendARental": "நீங்கள் <t0>வாடகை அல்லது தயாரிப்பு விசாரணை</t0> அனுப்பலாம். இந்த இணையதளம் விலைகள், கிடைக்கும் நிலை அல்லது பணம் செலுத்துதலைக் காட்டுவதில்லை. உங்கள் கோரிக்கை பற்றிப் பேச குழு பதில் அளிக்கும்.",
"contact.main.canISpeakMyMessage": "தட்டச்சு செய்வதற்குப் பதிலாக என் செய்தியைப் பேசிச் சொல்லலாமா?",
"contact.main.yesOnBrowsersThatSupport": "ஆம், குரல் தட்டச்சு வசதி உள்ள பிரவுசர்களில் (உதாரணமாக Android அல்லது கணினியில் Chrome). மைக்ரோஃபோனைத் தொட்டு English, हिन्दी அல்லது ಕನ್ನಡ என்பதைத் தேர்ந்தெடுங்கள். அனுப்புவதற்கு முன் எழுத்தைச் சரிபாருங்கள்.",
"contact.main.whatIfMyInternetConnection": "என் இணைய இணைப்பு துண்டிக்கப்பட்டால் என்ன ஆகும்?",
"contact.main.yourDraftIsKeptOn": "நீங்கள் தட்டச்சு செய்யும்போதே உங்கள் வரைவு இந்தச் சாதனத்தில் வைக்கப்படுகிறது. இணையம் இல்லாதபோது அனுப்பு என்பதை அழுத்தினால், செய்தி இந்தச் சாதனத்திலேயே காத்திருக்கும்; இந்தப் பக்கம் திறந்திருக்கும் வரை, இணைப்பு திரும்பியதும் அது தானாக அனுப்பப்படும்.",
