"contact.live.yourMessageWillSendWhen": "இணையம் திரும்பியதும் உங்கள் செய்தி அனுப்பப்படும்.",
"contact.live.youAppearToBeOffline": "உங்களுக்கு இணைய இணைப்பு இல்லை போலத் தெரிகிறது. உங்கள் செய்தி இந்தச் சாதனத்தில் சேமிக்கப்பட்டுள்ளது; இணைப்பு திரும்பியதும் தானாக அனுப்பப்படும். இந்தப் பக்கத்தைத் திறந்தே வைத்திருங்கள்.",
"contact.live.plantedAndWaitingForRain": "விதைக்கப்பட்டு மழைக்காகக் காத்திருக்கிறது — இணையம் வந்ததும் அனுப்பப்படும்.",
"diary.top.productConceptFutureFarmerApp": "<t0/>தயாரிப்பு கருத்து · எதிர்கால விவசாயி ஆப்",
"diary.top.theTaglineInSixIndian": "ஆறு இந்திய மொழிகளில் வாசகம். இந்தி: हर खेत की कहानी, अब आपकी डायरी में. கன்னடம்: ಪ್ರತಿ ಹೊಲದ ಕಥೆ, ಈಗ ನಿಮ್ಮ ಡೈರಿಯಲ್ಲಿ. தமிழ்: ஒவ்வொரு வயலின் கதையும், இப்போது உங்கள் டைரியில். தெலுங்கு: ప్రతి పొలం కథ, ఇప్పుడు మీ డైరీలో. மராத்தி: प्रत्येक शेताची कहाणी, आता तुमच्या डायरीत. மலையாளம்: ഓരോ കൃഷിയിടത്തിന്റെയും കഥ, ഇനി നിങ്ങളുടെ ഡയറിയിൽ.",
"diary.top.yourFarmYourRecordsYour": "உங்கள் பண்ணை. உங்கள் பதிவுகள். உங்கள் பயணம்.",
"diary.top.bhoomishaktiDiaryIsEnvisionedAs": "BhoomiShakti Diary என்பது விவசாயிகள் தங்கள் தினசரி பண்ணை வேலைகள், செலவுகள், பயிர் பதிவுகள் மற்றும் பருவ வரலாற்றை ஒழுங்குபடுத்த உதவும் எளிய டிஜிட்டல் பண்ணை டைரியாக உருவாக்கத் திட்டமிடப்பட்டுள்ளது — ஒரே இடத்தில், அவர்களின் சொந்த மொழியில்.",
"diary.top.exploreHowItWorks": "எப்படி வேலை செய்கிறது என்று பாருங்கள் <t0/>",
