"diary.records.everythingThatHappensOnThe": "பண்ணையில் நடக்கும் அனைத்தும், <t0>நினைவில் இருக்கும்.</t0>",
"diary.records.tenSimpleRecordTypesCover": "பத்து எளிய பதிவு வகைகள் விவசாயியின் முழு வேலை நாளையும் உள்ளடக்குகின்றன — புரியாத சொற்கள் நிறைந்த படிவங்கள் இல்லை.",
"diary.records.sowing": "விதைப்பு",
"diary.records.whichCropWhichFieldWhich": "எந்தப் பயிர், எந்த வயல், எந்த நாள் — ஒவ்வொரு பருவத்தின் தொடக்கம்.",
"diary.records.eachWateringSoYouKnow": "ஒவ்வொரு முறை நீர் பாய்ச்சியதும் பதிவாகும்; வயலுக்குக் கடைசியாக எப்போது தண்ணீர் கிடைத்தது என்று தெரிந்துகொள்ளலாம்.",
"diary.records.cropActivities": "பயிர் வேலைகள்",
"diary.records.weedingThinningStakingAndEvery": "களையெடுப்பு, பயிர் கலைத்தல், குச்சி நடுதல் மற்றும் இடையில் வரும் ஒவ்வொரு வேலையும்.",
"diary.records.farmInputs": "பண்ணை இடுபொருட்கள்",
"diary.records.seedsFertiliserAndSpraysWhat": "விதைகள், உரம் மற்றும் தெளிப்பு மருந்துகள் — எது, எப்போது பயன்படுத்தப்பட்டது.",
"diary.records.whoWorkedForHowLong": "யார் வேலை செய்தார், எவ்வளவு நேரம், எவ்வளவு கூலி கொடுக்கப்பட்டது.",
"diary.records.ploughingSowingAndHarvestingWork": "இயந்திரங்கள் மூலம் உழவு, விதைப்பு மற்றும் அறுவடை வேலைகள்.",
"diary.records.everyRupeeSpentOnThe": "பண்ணையில் செலவான ஒவ்வொரு ரூபாயும், ஒரே பட்டியலில்.",
"diary.records.soilActivities": "மண் வேலைகள்",
"diary.records.manureCompostSoilTestsAnd": "எரு, மட்கு உரம், மண் பரிசோதனை மற்றும் மண் பராமரிப்பு.",
"diary.records.harvest": "அறுவடை",
"diary.records.howMuchWasHarvestedAnd": "எவ்வளவு அறுவடை ஆனது, எந்த வயலிலிருந்து.",
"diary.records.farmNotes": "பண்ணைக் குறிப்புகள்",
"diary.records.anythingWorthRememberingInYour": "நினைவில் வைக்க வேண்டிய எதுவும் — உங்கள் சொந்த வார்த்தைகளில்.",
"diary.how.howBhoomishaktiDiaryWorks": "BhoomiShakti Diary எப்படி வேலை செய்கிறது",
"diary.how.aPathThroughTheFarming": "<t0>விவசாயப் பருவம்</t0> முழுவதும் ஒரு பாதை.",
"diary.how.sixSimpleStepsFromSetting": "ஆறு எளிய படிகள் — உங்கள் பண்ணையை அமைப்பது முதல் முழுப் பருவத்தையும் ஒரே பார்வையில் பார்ப்பது வரை. பாதையில் நடக்க ஸ்க்ரோல் செய்யுங்கள்.",
"diary.how.createMyFarm": "என் பண்ணையை உருவாக்கு",
"diary.how.villageLandAndIrrigationEntered": "கிராமம், நிலம் மற்றும் நீர்ப்பாசனம் — ஒரே ஒரு முறை உள்ளிட்டால் போதும்.",
"diary.how.addMyCrop": "என் பயிரைச் சேர்",
"diary.how.chooseTheCropAndThe": "பயிரையும் விதைப்புத் தேதியையும் தேர்ந்தெடுங்கள்.",
"diary.how.recordTodaysActivity": "இன்றைய வேலையைப் பதிவு செய்",
"diary.how.oneTapForIrrigationLabour": "நீர்ப்பாசனம், கூலி, இயந்திரம் அல்லது குறிப்புக்கு ஒரே தொடுதல்.",
"diary.how.trackWorkExpenses": "வேலை & செலவுகளைக் கண்காணி",
"diary.how.costsAddUpByThemselves": "நீங்கள் பதிவு செய்யச் செய்ய, செலவுகள் தானாகவே கூட்டப்படும்.",
