"diary.designed.eachIdeaStartsWithA": "ஒவ்வொரு யோசனையும் <t0>விவசாயியின் ஒரு உண்மையான பிரச்சினையிலிருந்து</t0> தொடங்குகிறது.",
"diary.designed.todayOnMyFarm": "இன்று என் பண்ணையில்",
"diary.designed.farmerProblemFarmersJuggleMany": "<t0>விவசாயியின் பிரச்சினை:</t0> விவசாயிகள் பல வேலைகளை ஒரே நேரத்தில் கவனிப்பதால், எது பாக்கி உள்ளது என்பதை மறந்துவிடுகிறார்கள்.",
"diary.designed.ideaOneScreenShowsTodays": "<t0>யோசனை:</t0> இன்றைய பதிவுகள், விதைத்து எத்தனை நாட்கள் ஆயின, என்ன திட்டமிடப்பட்டது என்பதை ஒரே திரை காட்டும்.",
"diary.designed.onetapRecord": "ஒரே தொடுதலில் பதிவு",
"diary.designed.farmerProblemTypingInThe": "<t0>விவசாயியின் பிரச்சினை:</t0> அழுக்கான கைகளுடனும் கடும் வெயிலிலும் வயலில் தட்டச்சு செய்வது மெதுவாக இருக்கும்.",
"diary.designed.ideaBigPictureButtonsRecord": "<t0>யோசனை:</t0> பெரிய படப் பட்டன்கள் மூலம் அடிக்கடி செய்யும் வேலைகளை ஒன்று அல்லது இரண்டு தொடுதல்களில் பதிவு செய்யலாம்.",
"diary.designed.cropMemory": "பயிர் நினைவகம்",
"diary.designed.farmerProblemWithSeveralCrops": "<t0>விவசாயியின் பிரச்சினை:</t0> பல பயிர்கள் இருக்கும்போது பதிவுகள் கலந்துவிடுகின்றன.",
"diary.designed.ideaEveryRecordIsFiled": "<t0>யோசனை:</t0> ஒவ்வொரு பதிவும் தானாகவே அதன் பயிர் மற்றும் வயலின் கீழ் வைக்கப்படும்.",
"diary.designed.seasonBook": "பருவப் புத்தகம்",
"diary.designed.farmerProblemPaperNotebooksGet": "<t0>விவசாயியின் பிரச்சினை:</t0> காகித நோட்டுப் புத்தகங்கள் தொலைந்துவிடுகின்றன அல்லது சேதமடைகின்றன.",
"diary.designed.ideaACompletePrintableRecord": "<t0>யோசனை:</t0> முழுப் பருவத்தின் முழுமையான, அச்சிடக்கூடிய பதிவு.",
"diary.designed.farmPassport": "பண்ணை பாஸ்போர்ட்",
"diary.designed.farmerProblemFarmHistoryIs": "<t0>விவசாயியின் பிரச்சினை:</t0> பண்ணை வரலாறு பல ஆண்டுகளிலும் பல நோட்டுப் புத்தகங்களிலும் சிதறிக் கிடக்கிறது.",
"diary.designed.ideaSeasonBooksStackInto": "<t0>யோசனை:</t0> பருவப் புத்தகங்கள் ஒன்றன் மேல் ஒன்றாகச் சேர்ந்து அதே நிலத்தின் நீண்ட கால வரலாறாக மாறும்.",
"diary.designed.shareMyFarmRecord": "என் பண்ணைப் பதிவைப் பகிர்",
"diary.designed.farmerProblemExplainingPastWork": "<t0>விவசாயியின் பிரச்சினை:</t0> கடந்த கால வேலைகளைக் குடும்பத்தினர், வாங்குபவர்கள் அல்லது அலுவலர்களிடம் விளக்குவது கடினம்.",
"diary.designed.ideaTheFarmerChoosesWhich": "<t0>யோசனை:</t0> எந்தப் பதிவுகளைப் பகிர வேண்டும் என்பதை விவசாயியே தேர்ந்தெடுப்பார் — எதுவும் தானாகப் பகிரப்படாது.",
"diary.designed.voiceNotes": "குரல் குறிப்புகள்",
"diary.designed.farmerProblemNotEveryFarmer": "<t0>விவசாயியின் பிரச்சினை:</t0> எல்லா விவசாயிகளுக்கும் தட்டச்சு செய்வது எளிதல்ல.",
"diary.designed.ideaSpeakAShortNote": "<t0>யோசனை:</t0> உங்கள் சொந்த மொழியில் ஒரு சிறு குறிப்பைப் பேசி, அதைப் பதிவுடன் வைத்துக்கொள்ளலாம்.",
"diary.designed.offlinefirst": "இணையம் இல்லாமலும் வேலை செய்யும்",
"diary.designed.farmerProblemMobileSignalIn": "<t0>விவசாயியின் பிரச்சினை:</t0> வயலில் மொபைல் சிக்னல் பலவீனமாக இருக்கும் அல்லது இருக்காது.",
"diary.designed.ideaRecordsSaveOnThe": "<t0>யோசனை:</t0> பதிவுகள் முதலில் போனிலேயே சேமிக்கப்படும்; இணையம் இல்லாமலும் வேலை செய்யும்.",
