"dyn.contact.micBlocked": "மைக்ரோஃபோன் அனுமதி தடுக்கப்பட்டது. உங்கள் பிரவுசர் அமைப்புகளில் மைக்ரோஃபோனை அனுமதியுங்கள், அல்லது உங்கள் செய்தியைத் தட்டச்சு செய்யுங்கள்.",
"dyn.contact.micOffline": "குரல் தட்டச்சுக்கு இணைய இணைப்பு தேவை. அதற்குப் பதிலாக உங்கள் செய்தியைத் தட்டச்சு செய்யலாம்.",
"dyn.contact.wait": "உங்கள் முந்தைய செய்தி இப்போதுதான் அனுப்பப்பட்டது. இன்னொன்றை அனுப்புவதற்கு முன் சில விநாடிகள் காத்திருக்கவும்.",
"dyn.contact.offlineNoSave": "உங்களுக்கு இணைய இணைப்பு இல்லை, இந்த பிரவுசரால் செய்தியைச் சேமிக்கவும் முடியவில்லை. இணையம் கிடைத்ததும் மீண்டும் முயற்சிக்கவும்.",
"dyn.contact.sdkBlocked": "மின்னஞ்சல் சேவை திறக்கவில்லை (உங்கள் நெட்வொர்க் அல்லது விளம்பரத் தடுப்பான் அதைத் தடுத்திருக்கலாம்). மீண்டும் முயற்சிக்கவும், அல்லது இந்தப் பக்கத்தில் உள்ள நேரடித் தொடர்பு விவரங்களைப் பயன்படுத்தவும்.",
"dyn.contact.tooMany": "குறுகிய நேரத்தில் அதிகமான செய்திகள். சிறிது நேரம் காத்திருந்து மீண்டும் முயற்சிக்கவும்.",
"dyn.contact.connection": "இணைப்புப் பிரச்சினையால் செய்தியை அனுப்ப முடியவில்லை. உங்கள் இணையத்தைச் சரிபார்த்து மீண்டும் முயற்சிக்கவும்.",
